    // Store links used by every CTA — the newrare site until the game has a
    // listing of its own.
    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },

    designWidth: 720,
    designHeight: 1280,
