    POWERS.forEach(function (p) { POWER[p.key] = p; });
    var ALL = POWERS.map(function (p) { return p.key; });
    var B1 = ["freeze", "stone"], B2 = ["ghostV", "ghostH", "mystery"], B3 = ["fire", "purple", "boltV", "boltH"],
        B4 = ["comet", "black", "switch"], B5 = ["teleport", "lock"];

    // ======================================================================
    //  THE FIVE BIOMES — one tile palette, one material, one scene each
    //  (docs/GELATILE.md §2.3). Every palette is a light one: the tiles go
    //  from very pale to medium-dark, always over a light scene.
    // ======================================================================
    var BIOMES = [
      { key: "bath",    name: "Bubble Bath",   h: [305, 275], L: [0.95, 0.52], C: [0.04, 0.17],
        tex: "textureSoap",    stand: "candy",   alpha: 0.5,  crop: 1,    scene: "sceneBath",
        music: { from: 25, length: 27.429, gain: 0.55 } },
      { key: "jungle",  name: "Jungle Lodge",  h: [118, 158], L: [0.94, 0.46], C: [0.06, 0.15],
        tex: "textureWood",    stand: "wood",    alpha: 0.55, crop: 0.7,  scene: "sceneJungle",
        music: { from: 55, length: 27.434, gain: 0.55 } },
      { key: "crystal", name: "Crystal Cave",  h: [215, 258], L: [0.96, 0.48], C: [0.03, 0.15],
        tex: "textureCrystal", stand: "crystal", alpha: 0.55, crop: 0.75, scene: "sceneCrystal",
        music: { from: 86, length: 27.429, gain: 0.55 } },
      { key: "rice",    name: "Rice Terraces", h: [355, 375], L: [0.94, 0.50], C: [0.05, 0.19],
        tex: "textureBamboo",  stand: "weave",   alpha: 0.45, crop: 0.8,  scene: "sceneRice",
        music: { from: 110, length: 27.429, gain: 0.55 } },
      { key: "beach",   name: "Coconut Beach", h: [170, 205], L: [0.95, 0.50], C: [0.05, 0.13],
        tex: "textureSand",    stand: "ripple",  alpha: 0.5,  crop: 0.8,  scene: "sceneBeach",
        music: { from: 140, length: 27.429, gain: 0.55 } }
    ];

    // From 128 up a tile starts to look premium: gold, then rainbow.
    var PREMIUM = [
      { from: 128,  rim: "gold",    rimW: 0.03 },
      { from: 256,  rim: "gold",    rimW: 0.04,  inner: true, sweep: 0.22 },
      { from: 512,  rim: "gold",    rimW: 0.05,  inner: true, sweep: 0.28, glints: 2 },
      { from: 1024, rim: "gold",    rimW: 0.055, inner: true, sweep: 0.35, glints: 4, goldText: true },
      { from: 2048, rim: "rainbow", rimW: 0.06,  inner: true, sweep: 0.4,  glints: 4, goldText: true },
      { from: 4096, rim: "rainbow", rimW: 0.065, inner: true, sweep: 0.45, glints: 4, goldText: true, holo: true }
    ];
    function premiumFor(v) {
      var p = null;
      for (var i = 0; i < PREMIUM.length; i++) if (v >= PREMIUM[i].from) p = PREMIUM[i];
      return p;
    }

    // ======================================================================
    //  THE THIRTY LEVELS (docs/GELATILE.md §6). `start` is laid as a snake
    //  from the bottom-left corner, biggest first; `par` is the second star,
    //  `bonus` the third; `mod` is the band's twist.
    // ======================================================================
    var LEVELS = [null,
      { goal: 128,  start: [],                              par: 95,  pool: [],            bonus: ["corner"] },
      { goal: 128,  start: [32, 16],                        par: 55,  pool: ["freeze"],    bonus: ["thaw", 2] },
      { goal: 256,  start: [64, 32],                        par: 120, pool: ["stone"],     bonus: ["noStone"] },
      { goal: 256,  start: [128],                           par: 65,  pool: ["freeze"],    bonus: ["multi", 3], mod: "clutter" },
      { goal: 256,  start: [64, 32, 32],                    par: 95,  pool: B1,            bonus: ["thaw", 3] },
      { goal: 512,  start: [128, 64, 32, 16],               par: 165, pool: B1,            bonus: ["corner"] },
      { goal: 256,  start: [64, 32],                        par: 125, pool: ["ghostV"],    bonus: ["ghostOut", 2] },
      { goal: 256,  start: [64, 32],                        par: 110, pool: ["ghostH"],    bonus: ["noGhostLost", 8] },
      { goal: 512,  start: [128, 64, 32],                   par: 185, pool: ["mystery"],   bonus: ["mystery", 2] },
      { goal: 512,  start: [128, 64],                       par: 260, pool: B2,            bonus: ["multi", 3], mod: "storm" },
      { goal: 512,  start: [256, 32],                       par: 145, pool: B1.concat(B2), bonus: ["thaw", 3] },
      { goal: 1024, start: [512, 256, 128],                 par: 115, pool: B1.concat(B2), bonus: ["corner"] },
      { goal: 512,  start: [128, 64, 32],                   par: 300, pool: ["fire"],      bonus: ["noBurn"] },
      { goal: 512,  start: [128, 64, 32, 16],               par: 310, pool: ["purple"],    bonus: ["noHalve"] },
      { goal: 512,  start: [256, 64],                       par: 260, pool: ["boltV", "boltH"], bonus: ["emptyBolt"] },
      { goal: 1024, start: [512, 256, 128, 64, 32],         par: 60,  pool: B3,            bonus: ["noLoss", 16], mod: "fours" },
      { goal: 1024, start: [512, 256, 128],                 par: 250, pool: B3.concat(B1), bonus: ["noLoss", 16] },
      { goal: 1024, start: [512, 256, 128],                 par: 220, pool: B1.concat(B2, B3), bonus: ["corner"] },
      { goal: 1024, start: [512, 256, 128, 64],             par: 85,  pool: ["comet"],     bonus: ["emptyComet"] },
      { goal: 1024, start: [512, 256, 128, 64],             par: 85,  pool: ["black"],     bonus: ["noHalve"] },
      { goal: 1024, start: [512, 256, 128],                 par: 105, pool: ["switch"],    bonus: ["switchMerge"] },
      { goal: 1024, start: [512, 256, 128],                 par: 285, pool: B4,            bonus: ["noLoss", 32], mod: "lasting" },
      { goal: 1024, start: [512, 256, 128, 64],             par: 130, pool: B3.concat(B4), bonus: ["noLoss", 32] },
      { goal: 2048, start: [1024, 512, 256, 128, 64],       par: 75,  pool: B1.concat(B2, B3, B4), bonus: ["corner"] },
      { goal: 1024, start: [512, 256, 128],                 par: 120, pool: ["teleport"],  bonus: ["portal", 5] },
      { goal: 1024, start: [512, 256, 128],                 par: 105, pool: ["lock"],      bonus: ["noRefuse"] },
      { goal: 1024, start: [512, 256, 128, 64],             par: 180, pool: B5.concat(B4), bonus: ["multi", 4] },
      { goal: 1024, start: [512, 256, 128],                 par: 115, pool: ALL,           bonus: ["noLoss", 32], mod: "counted" },
      { goal: 2048, start: [1024, 512, 256, 128, 64, 32],   par: 35,  pool: ALL,           bonus: ["noLoss", 64] },
      { goal: 2048, start: [1024, 512, 256, 128, 64],       par: 165, pool: ALL,           bonus: ["corner"] }
    ];
    // the playable is biome 1 with one tile power and one target; the
    // endless run, after level 30, deals every power from two tiles
    var FREE = { goal: 256, start: [128, 32, 32, 16, 8, 4], par: 60, pool: ["freeze", "fire"], bonus: null, first: 3 };
    var ENDLESS = { goal: 0, start: [], par: 0, pool: ALL, bonus: null };
    // the village's two modes (web.modes), both on biome 1 with no power:
    // CLASSIC runs until the board locks, for the best score; FAST is a race
    // to 2048 against the clock, its new tiles two notches under the biggest
    // one (spawnValue)
    var CLASSIC = { goal: 0, start: [], par: 0, pool: [], bonus: null };
    var FAST = { goal: 2048, start: [], par: 0, pool: [], bonus: null };
    var MODE_ROWS = { classic: CLASSIC, fast: FAST };

    var BONUS_TEXT = {
      corner: "End with the biggest tile in a corner",
      thaw: "Thaw {n} frozen tiles",
      noStone: "No stone on the board at the end of the game",
      multi: "{n} merges in one move",
      ghostOut: "Send {n} ghosts out",
      noGhostLost: "Lose no ghost above {n}",
      mystery: "Merge {n} mystery tiles",
      noBurn: "Burn no tile",
      noHalve: "Halve no tile",
      emptyBolt: "The bolt strikes nothing",
      noLoss: "Lose no tile above {n}",
      emptyComet: "Let a comet strike nothing",
      switchMerge: "Merge right after a switch",
      portal: "Send {n} tiles through the portal",
      noRefuse: "Make no refused move"
    };
    var MODS = {
      clutter: { name: "Clutter" },
      fours:   { name: "Four" },
      storm:   { name: "Storm" },
      lasting: { name: "Lasting" },
      counted: { name: "Counted" }
    };

    // ======================================================================
    //  STATE
    // ======================================================================
    var L = null, B = null, PAL = null, prevPAL = null, palT0 = -9, biomeIdx = 0;
    var grid = [], dying = [], events = [], particles = [], rings = [], fxs = [];
    var nextId = 1, score = 0, moves = 0, merges = 0, maxTile = 0;
    var cellPowers = [], sides = { left: null, right: null, up: null, down: null };
    var powerCountdown = 5, nextPower = null, incoming = null, clock = 0, levelD = null;
    // the warning sign: when it appeared, when it turned red
    var signOn = false, signRed = false, signAt = -9, redAt = -9;
    // the fast mode's clock: it starts on the first move and stops on 2048
    var runT = 0, runOn = false, runShown = -1;
    var won = false, over = false, ended = false, endAt = 0, outOfMoves = false, reached = false;
    var leanDir = null, leanTarget = 0, previewMap = null, previewValid = false, previewDirty = true;
    var nudge = null, flashA = 0, shakeAmp = 0, shakeX = 0, shakeY = 0, wallFlash = null;
    var drag = null, magnetTarget = {}, links = [], placed = false, lockSaid = false;
    var goldSeen = {};
    // the third star's counters
    var stats;
    // geometry, design px
    var BX = 0, BY = 0, S = 0, GAP = 0, CELL = 0;
    var dc = null;   // the context the drawing goes to: the round's, or a guide picture's

    var DV = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1] };
    var SIDES = ["left", "right", "up", "down"];
    var OPP = { left: "right", right: "left", up: "down", down: "up" };

    function isLevel() { return !!CONFIG.level && CONFIG.level > 0; }
    // the mode the shell armed (CONFIG.mode), never over a level
    function modeKey() { return !isLevel() && MODE_ROWS[CONFIG.mode] ? CONFIG.mode : null; }
    function isEndless() { return CONFIG.level === 0 && !!(CONFIG.web && CONFIG.web.levels) && !modeKey(); }
    function levelRow() {
      if (isLevel()) return LEVELS[clamp(CONFIG.level | 0, 1, 30)];
      if (modeKey()) return MODE_ROWS[modeKey()];
      if (isEndless()) return ENDLESS;
      return FREE;
    }
    function bandOf(n) { return clamp(Math.floor((n - 1) / 6), 0, 4); }
    function randInt(a, b) { return a + Math.floor(Math.random() * (b - a + 1)); }
    function pick(a) { return a[Math.floor(Math.random() * a.length)]; }
    function shuffle(a) {
      for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)), t = a[i]; a[i] = a[j]; a[j] = t; }
      return a;
    }
    function lerp(a, b, k) { return a + (b - a) * k; }
    function later(at, fn) { events.push({ at: at, fn: fn }); }
    function img(key) { var im = ArtImages[key]; return im && im.complete && im.naturalWidth ? im : null; }
    function powerMoves() { return L && L.mod === "lasting" ? 8 : 5; }

    // ======================================================================
    //  COLOUR — every palette is a path through OKLCH: lightness, chroma and
    //  hue all move one step per value, so 2 → 4 → 8 reads as a climb.
    // ======================================================================
    function labToLin(Lc, a, b) {
      var l_ = Lc + 0.3963377774 * a + 0.2158037573 * b;
      var m_ = Lc - 0.1055613458 * a - 0.0638541728 * b;
      var s_ = Lc - 0.0894841775 * a - 1.2914855480 * b;
      var l = l_ * l_ * l_, m = m_ * m_ * m_, s = s_ * s_ * s_;
      return [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
             -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
             -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s];
    }
    function inGamut(c) {
      return c[0] >= -0.001 && c[0] <= 1.001 && c[1] >= -0.001 && c[1] <= 1.001 && c[2] >= -0.001 && c[2] <= 1.001;
    }
    function enc(x) {
      x = Math.max(0, Math.min(1, x));
      return x <= 0.0031308 ? 12.92 * x : 1.055 * Math.pow(x, 1 / 2.4) - 0.055;
    }
    function oklch(Lc, C, h) {
      Lc = Math.max(0, Math.min(1, Lc));
      var hr = h * Math.PI / 180, ca = Math.cos(hr), sa = Math.sin(hr);
      var lin = labToLin(Lc, C * ca, C * sa);
      if (!inGamut(lin)) {
        var lo = 0, hi = C;
        for (var i = 0; i < 18; i++) {
          var mid = (lo + hi) / 2;
          if (inGamut(labToLin(Lc, mid * ca, mid * sa))) lo = mid; else hi = mid;
        }
        lin = labToLin(Lc, lo * ca, lo * sa);
      }
      return [enc(lin[0]) * 255, enc(lin[1]) * 255, enc(lin[2]) * 255];
    }
    function css(c, a) {
      return "rgba(" + (c[0] | 0) + "," + (c[1] | 0) + "," + (c[2] | 0) + "," + (a == null ? 1 : a) + ")";
    }
    function hexRgb(h) { return [parseInt(h.substr(1, 2), 16), parseInt(h.substr(3, 2), 16), parseInt(h.substr(5, 2), 16)]; }

    var palettes = [];
    function buildPalette(b) {
      var h0 = b.h[0], h1 = b.h[1], hm = (h0 + h1) / 2, dir = h1 >= h0 ? 1 : -1, p = { b: b, tiles: [] };
      for (var n = 1; n <= 17; n++) {
        var t = (n - 1) / 10, Lc, C, h;
        if (t <= 1) {
          Lc = lerp(b.L[0], b.L[1], Math.pow(t, 0.92));
          C = lerp(b.C[0], b.C[1], t) + 0.025 * Math.sin(Math.PI * t);
          h = lerp(h0, h1, t);
        } else {
          // past 2048 the hue keeps walking and the tile wears a shine
          Lc = b.L[1] - 0.04 * Math.min(n - 11, 3);
          C = b.C[1];
          h = h1 + dir * 24 * (n - 11);
        }
        p.tiles.push({
          L: Lc, rgb: oklch(Lc, C, h),
          top: oklch(Lc + 0.045, C * 0.95, h), bot: oklch(Lc - 0.04, C * 1.05, h),
          light: oklch(Math.min(0.97, Lc + 0.2), C * 0.8, h),
          text: Lc > 0.7 ? oklch(0.3, 0.06, h) : oklch(0.985, 0.01, h)
        });
      }
      p.mystery = { L: 0.72, rgb: oklch(0.72, 0.004, hm), top: oklch(0.76, 0.004, hm),
                    bot: oklch(0.68, 0.004, hm), text: oklch(0.98, 0, 0) };
      // a light plate over the painted scene, in the biome's own hue
      p.board = oklch(0.84, 0.04, hm); p.cell = oklch(0.93, 0.025, hm);
      p.ink = oklch(0.3, 0.05, hm); p.bg = oklch(0.95, 0.02, h0); p.bg2 = oklch(0.88, 0.04, hm);
      return p;
    }
    BIOMES.forEach(function (b) { palettes.push(buildPalette(b)); });
    function tileOf(p, v) { return p.tiles[clamp(Math.round(Math.log2(v)), 1, 17) - 1]; }

    // ======================================================================
