            var px = hz ? r[0] + r[2] * f : r[0] + r[2] / 2 + v[0] * (ph * 8 - 2);
            var py = hz ? r[1] + r[3] / 2 + v[1] * (ph * 8 - 2) : r[1] + r[3] * f;
