      dying.forEach(function (t) { if (t.fx && (t.fx.kind === "away" || t.fx.kind === "exit")) paintTile(t); });
      live.sort(function (a, b) { return (a._top ? 1 : 0) - (b._top ? 1 : 0); });
      live.forEach(function (t) {
        if (Enter.begin(t._px, t._py)) { paintTile(t); Enter.end(); }
      });
